import pandas as pd
from itertools import product

path='/root/data.xlsx'
df=pd.read_excel(path, sheet_name='Data', header=8)
# keep only rows with turn number
cdf=df[df['Turn number'].notna()].copy()
# select columns
roll_cols=['Roll 1','Roll 2','Roll 3','Roll 4','Roll 5','Roll 6']
for col in ['Turn number','Game number']+roll_cols:
    cdf[col]=cdf[col].astype(int)

# function to compute categories

def turn_scores(rolls):
    high=max(rolls)
    low=min(rolls)
    from collections import Counter
    cnt=Counter(rolls)
    scores={
        'High and Often': high*cnt[high],
        'Summation': sum(rolls),
        'Highs and Lows': high*low*(high-low),
    }
    if len(set(rolls))==2:
        scores['Only two numbers']=30
    if set(rolls)=={1,2,3,4,5,6}:
        scores['All the numbers']=40
    # run of 4 consecutive inc or dec in order
    run=False
    for i in range(len(rolls)-3):
        a=rolls[i:i+4]
        if all(a[j+1]-a[j]==1 for j in range(3)) or all(a[j+1]-a[j]==-1 for j in range(3)):
            run=True
            break
    if run:
        scores['Ordered subset of four']=50
    return scores

# compute per turn
turn_scores_dict={}
for _,row in cdf.iterrows():
    rolls=[row[c] for c in roll_cols]
    turn_scores_dict[int(row['Turn number'])]=(int(row['Game number']), turn_scores(rolls))

# build games dict
from collections import defaultdict

game_turns=defaultdict(list)
for turn, (game, scores) in turn_scores_dict.items():
    game_turns[game].append(scores)

# function to compute best game score given list of turn score dicts

def best_game_score(turns):
    # turns is list of dicts (should be length 2)
    if len(turns)==0:
        return None
    if len(turns)==1:
        # only one turn: if forced, score as best available for that turn (no category conflict)
        # We'll return best score of that turn for now
        return max(turns[0].values())
    t1, t2 = turns[0], turns[1]
    best=None
    for cat1,score1 in t1.items():
        for cat2,score2 in t2.items():
            if cat1==cat2:
                continue
            total=score1+score2
            if best is None or total>best:
                best=total
    return best

# compute game scores
scoresA={}
for game in range(1,3001):
    scoresA[game]=best_game_score(game_turns.get(game,[]))

# scenario A: if game missing one turn, use best of single turn (as above)
# scenario B: drop games not having 2 turns
scoresB={}
for game in range(1,3001):
    turns=game_turns.get(game,[])
    if len(turns)==2:
        scoresB[game]=best_game_score(turns)

# scenario C: treat missing turn as 0? We'll compute by adding a dummy turn with zero scores across categories maybe? It's ambiguous.

def best_game_score_with_zero(turns):
    if len(turns)==2:
        return best_game_score(turns)
    if len(turns)==1:
        # dummy turn with zero for all categories (but still distinct category required)
        # To maximize, choose best cat from actual turn and any different cat from zero-turn (all zero)
        dummy={
            'High and Often':0,
            'Summation':0,
            'Highs and Lows':0,
            'Only two numbers':0,
            'All the numbers':0,
            'Ordered subset of four':0,
        }
        return best_game_score([turns[0], dummy])
    return None

scoresC={}
for game in range(1,3001):
    turns=game_turns.get(game,[])
    scoresC[game]=best_game_score_with_zero(turns)

# function to compute match diff

def match_diff(scores):
    p1=p2=0
    ties=0
    for g in range(1,3001,2):
        g1=g; g2=g+1
        if g2 not in scores or g1 not in scores:
            continue
        s1=scores[g1]; s2=scores[g2]
        if s1 is None or s2 is None:
            continue
        if s1>s2:
            p1+=1
        elif s2>s1:
            p2+=1
        else:
            ties+=1
    return p1,p2,ties,p1-p2

print('turns per game counts', {k:len(v) for k,v in game_turns.items() if len(v)!=2})
print('scenario A (single turn best):', match_diff(scoresA))
print('scenario B (drop incomplete):', match_diff(scoresB))
print('scenario C (missing turn zeros):', match_diff(scoresC))

